using EngineeringUnits.Fast;
using System;

/// <summary>
/// Molar density of the saturated vapour (dew) state of ammonia (Q = 1) from the triple point to the critical point: a table of
/// degree-6 polynomial segments in theta = 1 - T/Tc, 8 segments per octave of theta down to 2^-20
/// (see <see cref="AncillaryTable"/>). The last segment, the final 0.39 mK below Tc, is fitted in sqrt(theta)
/// because the dome closes like a power of theta there.
///
/// Max relative deviation: 9.8E-11 from CoolProp; 1.1E-9 from the EOS dome between 405 K and 6 mK below Tc;
/// 5.4E-8 from 6 mK to 0.4 mK and 3.6E-5 closer than that, which is the conditioning limit of the saturation
/// problem itself (a +-5% perturbed start re-converges to within 3e-7 at 0.2 mK and 1.5e-5 at 10 microK).
///
/// Generated by the psatexp harness (sfproto-results/psatexp, "gen" mode) - do not edit the table by hand.
/// Reference data: CoolProp 6.4.2dev PropsSI(T, Q) from 195.495 K to 405.0 K (5 mK steps, 0.5 mK above 400 K).
/// Above 405.0 K CoolProp's own saturation solver breaks down (non-monotonic from ~405.13 K, then garbage), so the
/// Gao et al. 2020 dome itself was followed by continuation (2x2 Newton on equal p and g, geometric steps in theta)
/// up to its critical point (Tc = 405.56 K, rhoc = 13696 mol/m3, p = 11363391.16 Pa).
/// </summary>
public static class DewDensity
{
    public const double Tmin = AncillaryTable.Ttriple;
    public const double Tmax = AncillaryTable.Tc;

    private const int Shift = 49;
    private const long FirstKey = 8023;
    private const int Count = 154;

    public static Molarity Density(Temperature t)
    {
        double theta = AncillaryTable.Theta(t);
        int k = AncillaryTable.Segment(theta, Shift, FirstKey, Count);
        return Molarity.FromMolesPerCubicMeter(AncillaryTable.Polynomial(Table, k, k == 0 ? Math.Sqrt(theta) : theta));
    }

